fix:
Sort entries/elements using a defined deterministic order before constructing the output, or use an ordered container such as `BTreeMap`. Preserve the serialized shape rather than replacing an object with a sorted array. For signatures or canonical protocols, apply the format's full canonicalization rules, including nested values, rather than assuming that sorting only top-level keys suffices.
```rust
fn serialize_config(map: &HashMap<String, String>) -> String {
    let mut keys: Vec<_> = map.keys().collect();
    keys.sort(); // Restores deterministic ordering
    let mut out = String::new();
    for k in keys {
        out.push_str(&format!("{}={};", k, map[k]));
    }
    out
}

fn serialize_payload(map: &HashMap<String, String>) -> String {
    let ordered: BTreeMap<_, _> = map.iter().collect();
    serde_json::to_string(&ordered).unwrap()
}
